            }
          }
        ]
      },
      "layout_investigation": {
        "type": "absolute",
        "options": {
          "width": 1460,
          "height": 830,
          "display": "auto-scale",
          "backgroundColor": "#17191b"
        },
        "structure": [
          {
            "item": "viz_1",
            "type": "block",
            "position": {
              "x": 20,
              "y": 0,
              "w": 1420,
              "h": 112
            }
          },
          {
            "item": "viz_12",
            "type": "block",
            "position": {
              "x": 20,
              "y": 130,
              "w": 710,
              "h": 320
            }
          },
          {
            "item": "viz_13",
            "type": "block",
            "position": {
              "x": 750,
              "y": 130,
              "w": 690,
              "h": 320
            }
          },
          {
            "item": "viz_14",
            "type": "block",
            "position": {
              "x": 20,
              "y": 470,
              "w": 1420,
              "h": 340
            }
          }
        ]
      },
      "layout_evidence": {
        "type": "absolute",
        "options": {
          "width": 1460,
          "height": 890,
          "display": "auto-scale",
          "backgroundColor": "#17191b"
        },
